contract CustodyVault {

    address public custodian;

    mapping(address=>uint256) public balances;

    constructor(){
        custodian = msg.sender;
    }

    function deposit(address token,uint256 amount) external {

        IERC20(token).transferFrom(
            msg.sender,
            address(this),
